import React, { useState } from 'react';
import axios from 'axios';
import { MapContainer, TileLayer, CircleMarker, Popup, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

export default function WaypointFuzzinessTool() {
    const [fuzziness, setFuzziness] = useState(100); // Default 100 meters
    const [clusters, setClusters] = useState([]);
    const [loading, setLoading] = useState(false);
    const [stats, setStats] = useState(null);

    const handlePreview = async () => {
        setLoading(true);
        try {
            const response = await axios.post('/api/tools/waypoints/preview', { fuzziness });
            setClusters(response.data.clusters || []);
            setStats({
                count: response.data.count,
                fuzziness: response.data.fuzziness
            });
        } catch (error) {
            console.error("Error fetching waypoint preview:", error);
        }
        setLoading(false);
    };

    // Calculate map center based on first cluster or default
    const mapCenter = clusters.length > 0 && clusters[0].center 
        ? [clusters[0].center.lat, clusters[0].center.lon] 
        : [39.8283, -98.5795]; // Default center of US

    return (
        <div className="bg-gray-800 rounded-lg shadow-xl p-6 space-y-6 mt-6">
            <div>
                <h3 className="text-xl font-semibold">Waypoint Clustering Sensitivity</h3>
                <p className="text-gray-400 mt-1 mb-4">
                    Adjust the "fuzziness" (in meters) for grouping start/end locations (waypoints). 
                    Points within this distance will be grouped into a single location ID.
                </p>
                <div className="flex items-center space-x-4">
                    <input 
                        type="range" 
                        min="10" 
                        max="1000" 
                        step="10" 
                        value={fuzziness} 
                        onChange={(e) => setFuzziness(parseInt(e.target.value))} 
                        className="w-64 accent-cyan-500" 
                    />
                    <span className="font-mono text-lg">{fuzziness} m</span>
                    <button 
                        onClick={handlePreview} 
                        disabled={loading} 
                        className="bg-cyan-600 hover:bg-cyan-700 px-4 py-2 rounded-md disabled:opacity-50 text-white font-medium transition-colors"
                    >
                        {loading ? 'Processing...' : 'Preview Clusters'}
                    </button>
                </div>
                {stats && (
                    <p className="mt-4 text-green-400">
                        Found {stats.count} unique locations (clusters) from trip data.
                    </p>
                )}
            </div>

            <div className="h-[500px] w-full bg-gray-900 rounded-lg overflow-hidden border border-gray-700 relative">
                {clusters.length > 0 ? (
                    <MapContainer 
                        center={mapCenter} 
                        zoom={5} 
                        style={{ height: '100%', width: '100%' }}
                    >
                        <TileLayer
                            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                        />

                        {clusters.map((cluster, idx) => (
                            <React.Fragment key={idx}>
                                {/* Cluster Center */}
                                <CircleMarker 
                                    center={[cluster.center.lat, cluster.center.lon]}
                                    pathOptions={{ color: '#10B981', fillColor: '#10B981', fillOpacity: 0.8 }}
                                    radius={8}
                                >
                                    <Tooltip direction="top" offset={[0, -10]} opacity={1}>
                                        <span>Cluster #{idx + 1} ({cluster.points.length} points)</span>
                                    </Tooltip>
                                </CircleMarker>

                                {/* Individual Points in Cluster */}
                                {cluster.points.map((point, pIdx) => (
                                    <CircleMarker 
                                        key={`${idx}-${pIdx}`}
                                        center={[point.lat, point.lon]}
                                        pathOptions={{ color: '#EF4444', fillColor: '#EF4444', fillOpacity: 0.6, weight: 1 }}
                                        radius={3}
                                    >
                                        <Popup>
                                            Log ID: {point.log_id} <br/> Type: {point.type}
                                        </Popup>
                                    </CircleMarker>
                                ))}
                            </React.Fragment>
                        ))}
                    </MapContainer>
                ) : (
                    <div className="flex items-center justify-center h-full text-gray-500">
                        No preview data available. Adjust settings and click "Preview".
                    </div>
                )}
            </div>
        </div>
    );
}
